const xmlData = $input.first().json.data;

const getTag = (xml, tag) => {
  const match = xml.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`));
  return match ? match[1].trim() : '';
};

const titleMatches = [...xmlData.matchAll(/<title>([\s\S]*?)<\/title>/g)];
const title = titleMatches.length > 1 ? titleMatches[1][1].trim() : titleMatches[0][1].trim();

const abstract = getTag(xmlData, 'summary');
const authorMatches = xmlData.matchAll(/<name>([\s\S]*?)<\/name>/g);
const authors = [...authorMatches].map(m => m[1].trim()).join(', ');
const category = xmlData.match(/term="([^"]+)"/)?.[1] || 'Other';
const arxiv_url = $('Code in JavaScript').first().json.arxiv_url || '';

return [{
  json: {
    title,
    abstract,
    authors,
    category,
    arxiv_url
  }
}];

