const title = $input.first().json.title || 'Unknown Title';
const authors = $input.first().json.authors || '';
const summary = $input.first().json.summary || '';
const arxiv_url = $input.first().json.arxiv_url || '';

const clean = (str) => str.replace(/[\n\r\t]/g, ' ').replace(/"/g, "'").trim();
const truncate = (str, max = 1900) => {
  const cleaned = clean(str);
  return cleaned.length > max ? cleaned.substring(0, max) + '...' : cleaned;
};

const now = new Date().toISOString();

const body = {
  parent: { database_id: "YOUR_NOTION_DATABASE_ID" },
  properties: {
    Title: { title: [{ text: { content: truncate(title) } }] },
    Authors: { rich_text: [{ text: { content: truncate(authors) } }] },
    Summary: { rich_text: [{ text: { content: truncate(summary) } }] },
    Category: { select: { name: "CS" } },
    url: { url: arxiv_url },
    "Date Added": { date: { start: now } }
  }
};

return [{
  json: {
    title: truncate(title),
    authors: truncate(authors),
    summary: truncate(summary),
    arxiv_url,
    notionBody: JSON.stringify(body)
  }
}];
